    categories:["Twenty-Sixth Army","Red Army armies","Southwestern Front","Defense of Kiev","Operation Barbarossa"],
    facts:[["Formation represented","First formation <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Formed","1940 <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Commander on 31 July","Lieutenant General Fyodor Kostenko <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Initial chief of staff","Major General Filipp Parusinov <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Superior command through July","Southwestern Front <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Initial sector","Przemyśl · Sambir <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Initial rifle corps","8th Rifle Corps <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Initial mobile force","8th Mechanized Corps <sup class='canon-note' data-provenance='p'>[p]</sup>"],["Working August role","Southern Kiev sector and counterattacks <sup class='canon-note' data-provenance='e'>[e]</sup>"],["Status after 1 August","Open in detail <sup class='canon-note' data-provenance='e'>[e]</sup>"],["Later fate","Open <sup class='canon-note' data-provenance='e'>[e]</sup>"]]
